-- Reassign audit log entries from duplicate (60003) to primary user (1)
UPDATE authAuditLog SET userId = 1 WHERE userId = 60003;

-- Now move the credential record to user 1
UPDATE localCredentials SET userId = 1, failedAttempts = 0, lockedUntil = NULL WHERE userId = 60003;

-- Delete the duplicate user
DELETE FROM users WHERE id = 60003;

